const ProjectCard: React.FC<{ project: Project; onOpen: (p: Project) => void }> = ({ project, onOpen }) => {
  const getStatusColor = (status: ProjectStatus) => {
    switch (status) {
      case ProjectStatus.LIVE: return 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
      case ProjectStatus.PROTOTYPE: return 'bg-blue-500/10 text-blue-400 border-blue-500/20';
      case ProjectStatus.IN_PROGRESS: return 'bg-slate-500/10 text-slate-400 border-slate-500/20';
      case ProjectStatus.COMPLETED: return 'bg-purple-500/10 text-purple-400 border-purple-500/20';
      default: return 'bg-white/5 text-white border-white/10';
    }
  };

  return (
    <motion.div
      layout
      initial={{ opacity: 0, scale: 0.98 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.98 }}
      whileHover={{ y: -2 }}
      transition={{ duration: 0.2 }}
      className="glass p-5 sm:p-6 rounded-2xl flex flex-col h-full group hover:border-blue-500/30 transition-all cursor-pointer relative overflow-hidden"
      onClick={() => onOpen(project)}
    >
      <div className="flex justify-between items-center mb-4">
        <span className={`px-2 py-0.5 rounded-md text-[8px] font-black uppercase tracking-[0.15em] border ${getStatusColor(project.status)}`}>
          {project.status}
        </span>
        <div className="text-slate-600 group-hover:text-blue-400 transition-colors">
          <ChevronRight size={14} />
        </div>
      </div>

      <h3 className="text-lg font-bold mb-2 group-hover:text-blue-400 transition-colors line-clamp-1">{project.title}</h3>
      <p className="text-slate-400 text-xs mb-5 flex-grow line-clamp-2 leading-relaxed opacity-80">{project.description}</p>

      <div className="flex flex-wrap gap-1.5 mb-6">
        {project.tags.slice(0, 3).map(tag => (
          <span key={tag} className="px-1.5 py-0.5 rounded bg-white/5 text-[8px] text-slate-500 uppercase font-black whitespace-nowrap border border-white/5">
            {tag}
          </span>
        ))}
      </div>

      <div className="pt-3 border-t border-white/5 flex items-center justify-between mt-auto">
        <div className="text-[9px] text-slate-500 font-bold uppercase tracking-wide flex items-center gap-1.5">
          <User size={10} className="text-blue-500/50" />
          <span className="truncate max-w-[100px]">{project.role}</span>
        </div>

        <div className="flex justify-end">
          {project.isPrivate ? (
            <div className="flex items-center gap-1 text-slate-600 text-[9px] font-black uppercase">
              <Lock size={10} /> Private
            </div>
          ) : (
            <div className="text-blue-500/70 group-hover:text-blue-400 text-[9px] font-black uppercase tracking-widest flex items-center gap-1 transition-colors">
              Details <ArrowUpRight size={10} />
            </div>
          )}
        </div>
      </div>
    </motion.div>
  );
};

