          </div>

          <div className="overflow-y-auto p-6 space-y-8 custom-scrollbar">
            <div className="space-y-6">
              <div className="p-4 rounded-xl bg-blue-500/5 border border-blue-500/10">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Outcome</h4>
                <p className="text-slate-200 text-sm leading-relaxed font-medium">{project.outcome}</p>
              </div>

              <div className="space-y-2">
                <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Description</h4>
                <p className="text-slate-400 text-sm leading-relaxed">{project.description}</p>
              </div>

              {project.subLinks && project.subLinks.length > 0 && (
                <div className="space-y-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Sparkles size={12} className="text-blue-400" /> Assets & Links
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                    {project.subLinks.map((sub, i) => (
                      <a 
                        key={i} 
                        href={sub.url} 
