                      >
                        <span className="text-[11px] font-bold text-slate-300 truncate pr-2">{sub.name}</span>
                        <ArrowUpRight size={12} className="text-slate-500 group-hover/sub:text-white transition-colors" />
                      </a>
                    ))}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-6 pt-4 border-t border-white/5">
                <div>
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Role</h4>
                  <div className="flex items-center gap-2 text-slate-300 text-[11px] font-bold">
                    <User size={12} className="text-blue-500" />
                    {project.role}
                  </div>
                </div>
                <div>
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Stack</h4>
                  <div className="flex flex-wrap gap-1.5">
                    {project.tags.map(tag => (
                      <span key={tag} className="px-1.5 py-0.5 rounded bg-white/5 border border-white/10 text-[8px] text-slate-500 uppercase font-black">{tag}</span>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="p-6 border-t border-white/5 bg-white/[0.02]">
            {project.isPrivate ? (
              <div className="flex flex-col gap-2">
                <div className="w-full py-3 rounded-xl bg-slate-800/50 text-slate-500 font-black text-[10px] uppercase tracking-widest text-center border border-white/5 opacity-50 flex items-center justify-center gap-2">
                  Access Restricted <Lock size={12} />
                </div>
                <p className="text-[8px] text-center text-slate-600 italic">System resources limited to authorized partners.</p>
              </div>
            ) : project.link ? (
              <a 
                href={project.link} 
                target="_blank" 
                rel="noopener noreferrer" 
                className="flex items-center justify-center gap-2 w-full py-3 rounded-xl bg-blue-600 text-white font-black text-xs uppercase tracking-widest hover:bg-blue-500 transition-all active:scale-[0.98] shadow-lg shadow-blue-900/40"
              >
                Visit Project <ExternalLink size={14} />
              </a>
            ) : (
              <div className="w-full py-3 rounded-xl bg-white/5 text-slate-600 font-black text-xs text-center border border-white/10 uppercase tracking-widest">
                Deployment Pending
              </div>
            )}
          </div>
        </motion.div>
      </motion.div>
    </>
  );
};

const Projects: React.FC = () => {
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [activeFilter, setActiveFilter] = useState<ProjectStatus | 'All'>('All');

  const filters: (ProjectStatus | 'All')[] = [
    'All',
    ProjectStatus.LIVE,
    ProjectStatus.PROTOTYPE,
    ProjectStatus.IN_PROGRESS,
  ];

  const filteredProjects = activeFilter === 'All' 
    ? PROJECTS 
    : PROJECTS.filter(p => p.status === activeFilter);

  useEffect(() => {
    if (selectedProject) {
      document.body.classList.add('modal-open');
    } else {
      document.body.classList.remove('modal-open');
    }
    return () => document.body.classList.remove('modal-open');
  }, [selectedProject]);

  return (
    <section id="projects" className="py-12 border-t border-white/5">
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 mb-10">
        <div>
          <h2 className="text-2xl font-bold mb-2">Projects</h2>
          <p className="text-slate-500 text-xs font-medium uppercase tracking-widest">Select systems and experiments</p>
        </div>

        <div className="flex items-center gap-1.5 p-1 rounded-xl bg-white/5 border border-white/5 self-start lg:self-center">
          {filters.map((f) => (
            <button
              key={f}
              onClick={() => setActiveFilter(f)}
              className={`px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-wider transition-all ${
                activeFilter === f
                  ? 'bg-blue-600 text-white shadow-md shadow-blue-900/20'
                  : 'text-slate-500 hover:text-slate-300'
              }`}
            >
              {f}
            </button>
          ))}
        </div>
      </div>

      <motion.div 
        layout
        className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5"
      >
        <AnimatePresence mode="popLayout">
          {filteredProjects.map((project) => (
            <ProjectCard 
              key={project.id} 
              project={project} 
              onOpen={setSelectedProject} 
            />
          ))}
        </AnimatePresence>
      </motion.div>

      <AnimatePresence mode="wait">
        {selectedProject && (
          <ProjectModal 
            key={`modal-${selectedProject.id}`}
            project={selectedProject} 
            onClose={() => setSelectedProject(null)} 
          />
        )}
      </AnimatePresence>
    </section>
  );
};

export default Projects;

